MultiLanguageSpellData['mx'][88741] = {name = "Draco del viento del Oeste", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira a un draco del Viento del Oeste que se puede montar. Es una montura voladora.\n[q]\"Invocar los poderes elementales de la tormenta, estas majestuosas bestias crujen como un rayo y rugen como un trueno.\"\nVendedor:\nIntendente Brazie\nZona:\nPenínsula de Tol Barad\nFacción\nCeladores de Baradin - Exaltado"}
MultiLanguageSpellData['mx'][88742] = {name = "Draco del viento del Norte", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira a un draco del Viento del Norte que se puede montar. Es una montura voladora.\n[q]\"A ellos les enferma la calma de los que conocen la tormenta.\"\nBotín:\nAltairus\nZona:\nLa Cumbre del Vórtice"}
