MultiLanguageSpellData['mx'][88907] = {name = "[q0]Fetiche de Hir'eek", additional_info = "Hechizo de 2 seg 5\n[q]Hir'eek es uno de los espíritus animales adorados por los trols del sur. El animal totémico de Hir'eek es el murciélago. Jeklik, una suma sacerdotisa de Zandalar, fue una de las seguidoras más famosas de Hir'eek.\n[q0]Fetiche de Hir'eek\nSe liga al recogerlo"}
MultiLanguageSpellData['mx'][88908] = {name = "[q0]Talismán de pie de lagarto", additional_info = "Hechizo de 2 seg 5\n[q]Se trata de un pequeño pie momificado de un lagarto de la jungla. La magia que una vez contuvo ha desaparecido desde entonces.\n[q0]Talismán de pie de lagarto\nSe liga al recogerlo"}
MultiLanguageSpellData['mx'][88909] = {name = "[q0]Silbato de madera", additional_info = "Hechizo de 2 seg 5\n[q]Se trata de un pequeño silbato tallado en roble. Puede que se utilizase para invocar a una mascota o montura o, posiblemente, como juguete de un niño. Parece que lo ha mordido algún animal o un enano joven.\n[q0]Silbato de madera\nSe liga al recogerlo"}
MultiLanguageSpellData['mx'][88910] = {name = "[q0]Hebilla con el blasón de Yunquemar", additional_info = "Hechizo de 2 seg 5\n[q]Modimus Yunquemar fue el rey de los enanos antes de la Guerra de los Tres Martillos y está representado por una gran estatua a las puertas de Forjaz. Puede que esta hebilla de latón haya pertenecido a un miembro de la guardia de su casa o a un sirviente.\n[q0]Hebilla con el blasón de Yunquemar\nSe liga al recogerlo"}
