MultiLanguageSpellData['mx'][90528] = {name = "See Quest Invis 5", additional_info = nil}
MultiLanguageSpellData['mx'][90546] = {name = "Guarda patán", additional_info = "Instante\n[q]Poderoso por un poderoso patán. Helix no puede morir mientras su patán avanza."}
MultiLanguageSpellData['mx'][90550] = {name = "Tromba Arcana", additional_info = "100 maná Alcance de 30 m\nHechizo de 2 seg\n[q]Lanza contra el objetivo enemigo varios misiles que le infligen daño Arcano."}
MultiLanguageSpellData['mx'][90551] = {name = "Poder sobrecogedor", additional_info = "Alcance de 100 m\nHechizo de 5 seg\n[q]Lanza un arco de magia, lo que inflige daño Arcano al objetivo enemigo."}
MultiLanguageSpellData['mx'][90553] = {name = "[q3]Cáliz de los reyes de la montaña", additional_info = "Hechizo de 2 seg 15\n[q]\"Además de las muchas joyas que lo adornan, este cáliz está virtualmente cubierto de runas para celebrar una antigua ceremonia de ascensión para los reyes enanos. Beber de este cáliz era, sin duda, parte de ella, pero las runas describen una \"danza de espadas\" llevada a cabo por enanas guerreras. Este acto, en parte ritual y en parte representación de batalla, evolucionó aparentemente a partir de duelos sangrientos de épocas menos sofisticadas de la historia de los enanos\".\n[q3]Cáliz de los reyes de la montaña\nSe liga al recogerlo\nJuguete\n[q2]Uso: Presencia una danza de espadas histórica. (10 Min Reutilización)"}
