MultiLanguageSpellData['mx'][90950] = {name = "Llamas devoradoras", additional_info = "Rango ilimitado\nHechizo de 2.5 seg\n[q]Las Llamas devoradoras infligen 11344653 p. de daño de las Sombras cada 1 s y el daño se reduce cuanto más lejos está el objetivo del origen de las Llamas devoradoras."}
