MultiLanguageSpellData['mx'][90960] = {name = "Hojas giratorias", additional_info = "{40 p. de energía} {Alcance de 35 m}\nInstante\nRequiere Armas\n[q]Rodea al enemigo con hojas giratorias. Inflige daño físico a todas las unidades cercanas."}
