MultiLanguageSpellData['mx'][90968] = {name = "[q0]Vaina de espada barroca", additional_info = "Hechizo de 2 seg 5\n[q]Esta vaina de espada tiene una ornamentación casi desagradable. En toda la superficie visible se ha tallado, dorado o se han hecho inscripciones. Es probable que el arma que una vez llevó envainada fuese de una naturaleza muy mágica o ceremonial.\n[q0]Vaina de espada barroca\nSe liga al recogerlo"}
MultiLanguageSpellData['mx'][90969] = {name = "Cancelar detección de invisibilidad", additional_info = nil}
MultiLanguageSpellData['mx'][90971] = {name = "Absorber espíritu", additional_info = nil}
MultiLanguageSpellData['mx'][90974] = {name = "[q0]Candelabro de cristal refinado", additional_info = "Hechizo de 2 seg 5\n[q]Esta pieza tuvo un día una docena de velas. Está cubierta de cristales azules y violetas conectados por finas cadenas y ornamentos para decorar. Las iniciales del artesano están grabadas en el fondo: \"V. T.\".\n[q0]Candelabro de cristal refinado\nSe liga al recogerlo"}
MultiLanguageSpellData['mx'][90975] = {name = "[q0]Retrato dignificado", additional_info = "Hechizo de 2 seg 5\n[q]Se trata de una pintura al óleo muy seria de un caballero draenei muy serio. Aunque la obra es en general halagadora, puedes notar que al artista no le caía muy bien el modelo, ya que en la parte inferior del cuadro puedes ver cómo pintó al caballero sin pantalones.\n[q0]Retrato dignificado\nSe liga al recogerlo"}
MultiLanguageSpellData['mx'][90976] = {name = "Llamada de alma en pena", additional_info = "Alcance de 45 m\nInstante\n[q]Invoca una alma en pena para que recoja a un agente de la IV:7 herido. El objetivo debe tener un 35% de salud o menos."}
MultiLanguageSpellData['mx'][90977] = {name = "Invocar Hablaalmas", additional_info = nil}
MultiLanguageSpellData['mx'][90978] = {name = "¡Energizar!", additional_info = "Hechizo de 3 seg\n[q]Aumenta la velocidad de lanzamiento y de ataque un 50% y el daño físico que inflige un 25%."}
MultiLanguageSpellData['mx'][90980] = {name = "Rajar", additional_info = "Alcance de ataques cuerpo a cuerpo\nSiguiente cuerpo a cuerpo\n[q]Inflige un 150% de daño cuerpo a cuerpo normal a un enemigo y a sus aliados cercanos. Afecta hasta a 3 objetivos."}
MultiLanguageSpellData['mx'][90983] = {name = "[q3]Llegada de los Naaru", additional_info = "Hechizo de 2 seg 15\n[q]El cristal parece ser un dispositivo de grabación mágico de algún tipo. El mensaje que reproduce está en un idioma que no puedes descifrar del todo, pero deduces que es o bien una grabación o una recreación del primer encuentro de los eredar y los naaru.\n[q3]Llegada de los Naaru\nSe liga al recogerlo\nJuguete\n[q2]Uso: Presencia una grabación de la llegada de los Naaru. (3 Min Reutilización)"}
MultiLanguageSpellData['mx'][90984] = {name = "[q3]La última reliquia de Argus", additional_info = "Hechizo de 2 seg 15\n[q]Antes de vivir en Azeroth o en Draenor, los draenei, que aún eran eredar en aquel momento, vivían en Argus. Cuando Sargeras se dio cuenta de la existencia de Argus, el profeta Velen huyó con algunos miembros de su pueblo, que hoy conocemos como los draenei. Los demás eredar fueron absorbidos por la Legión Ardiente. Este cristal simple se extrajo de Argus cuando Velen huyó. La inscripción del fondo dice 'Añoro a Eredath.'\n[q3]La última reliquia de Argus\nSe liga al recogerlo\n[q2]Uso: Te teletransporta exactamente adonde quieres ir... si no eres muy exigente. (12 H Reutilización)\n[q]\"Una de las pocas cosas que consiguieron llevarse los draenei en su vuelo desde Argus.\""}
MultiLanguageSpellData['mx'][90985] = {name = "Vientos de los muertos", additional_info = "Instante\n[q]El intelecto aumenta 2 p. durante 15 s."}
MultiLanguageSpellData['mx'][90986] = {name = "Vientos de los muertos", additional_info = "[q]Tus hechizos periódicos de sanación y de daño otorgan 2 p. de intelecto cada vez que sanan o infligen daño. Dura 15 s y se acumula hasta 20 veces.\n(500ms de reutilización)"}
MultiLanguageSpellData['mx'][90987] = {name = "[q0]Fusta de elekk chapada", additional_info = "Hechizo de 2 seg 5\n[q]Los elekk son criaturas nativas de Draenor, concretamente de la zona de Nagrand, parecidas a los mamuts. Los draenei domesticaron a los elekk para usarlos como monturas. Esta fusta es un palo largo con punta que se usa para motivar a los elekk hoscos que no han completado su entrenamiento.\n[q0]Fusta de elekk chapada\nSe liga al recogerlo"}
MultiLanguageSpellData['mx'][90988] = {name = "[q0]Llave de la arqueta intrincada", additional_info = "Hechizo de 2 seg 5\n[q]Aunque la tecnología vrykul está en general un poco por detrás de la de la Horda o la Alianza, el detalle del diseño de esta simple llave es impresionante. En la cultura vrykul, es la mujer de la casa la que guarda todas las llaves y a menudo las exhibe para mostrar su estatus. \"No abre el cofre del clérigo oscuro Salem\".\n[q0]Llave de la arqueta intrincada\nSe liga al recogerlo"}
