MultiLanguageSpellData['mx'][90994] = {name = "Túnel", additional_info = "Alcance de 40 m\nHechizo de 1 seg\n[q]Cava un túnel en la tierra debajo del taumaturgo, lo que hace que desaparezca durante hasta que se cancela."}
MultiLanguageSpellData['mx'][90996] = {name = "Crescendo de sufrimiento", additional_info = "Instante\n[q]Poder con hechizos aumentado 226 p. durante 10 s."}
MultiLanguageSpellData['mx'][90997] = {name = "[q4]Hacha barbada Nafsavar", additional_info = "Hechizo de 2 seg 15\n[q]Muchas de las hachas forjadas por los vrykul presentan un estilo inusual: el borde inferior de la hoja del hacha sobrepasa la extensión del ancho de la parte inferior. Este estilo aumenta la zona de corte a la vez que minimiza el peso; se puede utilizar tanto en armas como herramientas. Algunas hachas enanas presentan una construcción similar.\n[q4]Hacha barbada Nafsavar\n[q7]Se liga a la tropa\nUna mano Hacha\n3 - 8 p. de daño Velocidad 2.60\n(2.1 p. de daño por segundo)\n+1 agilidad\n+4 aguante\n[q2]Aumenta tu índice de golpe crítico + 2 p.\n[q2]Aumenta tu índice de celeridad + 1 p.\nDurabilidad 110 / 110\nNecesitas ser de nivel 27"}
MultiLanguageSpellData['mx'][90998] = {name = "Canto de aflicción", additional_info = "[q]Tus hechizos que infligen daño a un objetivo con menos de un 35% de salud otorgan 226 p. de poder con hechizos durante 10 s. No se puede volver a activar hasta 10 s después de que expire el bonus.\n(20s de reutilización)"}
