MultiLanguageSpellData['mx'][91002] = {name = "Crescendo de sufrimiento", additional_info = "Instante\n[q]Tus hechizos que infligen daño a un objetivo con menos de un 35% de salud otorgan 114 p. de poder con hechizos durante 10 s. No se puede volver a activar hasta 10 s después de que expire el bonus."}
