MultiLanguageSpellData['mx'][91004] = {name = "Fuego Sagrado", additional_info = "1000 maná Alcance de 30 m\nHechizo de 5 seg\n[q]Envuelve a un enemigo en llamas, quemándolo e infligiendo daño de Fuego extra cada 2 s durante 8 s."}
MultiLanguageSpellData['mx'][91007] = {name = "Magia temible", additional_info = "Instante\n[q]Poder con hechizos aumentado 226 p. durante 20 s."}
MultiLanguageSpellData['mx'][91008] = {name = "[q0]Chaira", additional_info = "Hechizo de 2 seg 5\n[q]Las chairas son cuchillos grandes y rectos con un solo filo y una empuñadura simple que llevaban muchos guerreros vrykul como arma lateral. Un estilo de lucha común entre los guerreros consiste en tener el hacha en la mano derecha y la chaira en la izquierda.\n[q0]Chaira\nSe liga al recogerlo"}
MultiLanguageSpellData['mx'][91009] = {name = "Fuerza renegada", additional_info = "Instante\n[q]Colma al objetivo con la fuerza de los Defias. Aumenta el daño físico un 200%, reduce el daño recibido de los hechizos y facultades de área de efecto un 90% y aumenta la salud un 300%."}
MultiLanguageSpellData['mx'][91011] = {name = "Item - Proc Spell Power On Dmg", additional_info = "[q]Tus hechizos dañinos tienen una probabilidad de otorgarte 226 p. de poder con hechizos durante 20 s.\n(Probabilidad de que accione: 20%, 1.667m de reutilización)"}
MultiLanguageSpellData['mx'][91012] = {name = "[q0]Asediador de sílex", additional_info = "Hechizo de 2 seg 5\n[q]Este sencillo asediador de sílex se utilizaba para encender fuego. La vara está tallada como la cabeza de un dragón, mientras que la hoja plana de metal está decorada para que parezca un pez estilizado.\n[q0]Asediador de sílex\nSe liga al recogerlo"}
MultiLanguageSpellData['mx'][91013] = {name = "Temporraíz", additional_info = "Instante\n[q]Aumenta tu poder con hechizos 1926 p. durante 15 s."}
MultiLanguageSpellData['mx'][91014] = {name = "[q0]Fíbula de capa dentuda", additional_info = "Hechizo de 2 seg 5\n[q]Este broche se debe haber utilizado para atar una gran capa vrykul sobre los hombros. Fijados a la fíbula cruciforme son dos grandes dientes desgastados, muy probablemente de un protodraco camino de la vejez. No queda claro si el propietario del broche sentía alguna afinidad por el viejo draco o si esa criatura fue lo único que era capaz de derrotar.\n[q0]Fíbula de capa dentuda\nSe liga al recogerlo"}
