MultiLanguageSpellData['mx'][93325] = {name = "Ola de choque", additional_info = "Alcance de ataques cuerpo a cuerpo\nHechizo de 1 seg\n[q]Envía una ola de fuerza frente al taumaturgo que inflige 3696 p. de daño y aturde a todos los objetivos enemigos en un radio de 15 m en un cono frontal durante 3 s."}
MultiLanguageSpellData['mx'][93326] = {name = "Draco de arenisca", additional_info = "Hechizo de 1.5 seg\n[q]Te transforma en draco de arenisca, lo que te permite volar muy rápido y llevar un aliado. Es una montura voladora.\n[q]\"Los dracos de arenisca fueron estudiados en profundidad hace mucho tiempo por el famoso alquimista Leucoma Engranágil. Se dice que Leucoma desarrolló pociones que imitan la fisiología del draco.\"\nProfesión:\nAlquimia"}
MultiLanguageSpellData['mx'][93327] = {name = "Sepultar", additional_info = "Alcance de 20 m\nInstante\n[q]Machacando a un objetivo con un abrazo terráneo, lo que inflige 341 p. de daño cada 2 s durante 30 s. Las aplicaciones extra intensificarán el dolor, pero la exposición a un viento intenso puede contrarrestar el efecto."}
MultiLanguageSpellData['mx'][93328] = {name = "[q4]Vial de las arenas", additional_info = "Hechizo de 3.5 seg\nComponentes:\nVial cristalino con cordones de pirium , Arenas del tiempo (8), Veraoro (12), Frasco de los vientos (8), Frasco de fuerza titánica (8), Aceite Piedraprofunda (8)\nProfesión:\nArqueología\nBotín:\nVaso canope\n\n\n[q4]Vial de las arenas\nMontura[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a transformarte en un dragón, lo que te permite llevar a un aliado. Es una montura voladora.\n[q2]Te transforma en draco de arenisca, lo que te permite volar muy rápido y llevar un aliado. Es una montura voladora.\n1 - 80 ( 80)\nRequiereAprendiz jinete\n[q]\"Los dracos de arenisca fueron estudiados en profundidad hace mucho tiempo por el famoso alquimista Leucoma Engranágil. Se dice que Leucoma desarrolló pociones que imitan la fisiología del draco.\"\nProfesión:\nAlquimia"}
