MultiLanguageSpellData['mx'][93336] = {name = "Resguardo de combustión", additional_info = "Instante\n[q]Aire muy caliente se arremolina alrededor del taumaturgo, lo que inflige daño a todos los atacantes. Se requiere algún tipo de protección contra la llama intensa para atacar con seguridad a través de la barrera."}
