MultiLanguageSpellData['mx'][93433] = {name = "Ataque de enterramiento", additional_info = "10 enfoque, más 5 por sCanalizado (Hechizo de 8 seg) 14 seg de reutilización\n[q]El gusano se entierra en el suelo, lo que sacude el terreno de encima e inflige [(([12.1% of Attack Power]) + ((Poder de ataque a distancia * 0.60) * 0.096)) * 8 * (1 + Versatilidad) * 1 ] p. de daño de Naturaleza durante 8 s."}
MultiLanguageSpellData['mx'][93440] = {name = "[q0]Calcetines de bebé enano", additional_info = "Hechizo de 2 seg 5\n[q]Al principio creías que estaban petrificados. Pero no, solo son duros.\n[q0]Calcetines de bebé enano\nSe liga al recogerlo"}
MultiLanguageSpellData['mx'][93441] = {name = "[q0]Collar con colgante de Elune", additional_info = "Hechizo de 2 seg 5\n[q]Elune es la diosa principal de los elfos de la noche. Está asociada con la más grande de las dos lunas, la Dama Blanca. Aunque es una diosa de paz, no es una pacifista. Uno de sus aspectos es el Guerrero nocturno, que lleva su valor entre los muertos y los hace volar por el cielo como estrellas.\n[q0]Collar con colgante de Elune\nSe liga al recogerlo"}
MultiLanguageSpellData['mx'][93442] = {name = "[q0]Fragmento de madera petrificada", additional_info = "Hechizo de 2 seg 5\n[q]Aunque no queda nada de tejido en sí, la estructura vascular de la madera se conserva perfectamente. La planta era seguramente una cicas o una palmera de alguna clase.\n[q0]Fragmento de madera petrificada\nSe liga al recogerlo"}
MultiLanguageSpellData['mx'][93443] = {name = "[q0]Onicóforo extraño", additional_info = "Hechizo de 2 seg 5\n[q]Parece que al fósil le falta alguna conexión de algún tipo. Comparte propiedades de ambos artrópodos y gusanos. Su cuerpo es como el de un gusano, pero tiene piernas fornidas como las de un insecto o crustáceo. Parece haber estado cubierto de un pelo fino semejante al cuero.\n[q0]Onicóforo extraño\nSe liga al recogerlo"}
MultiLanguageSpellData['mx'][93444] = {name = "[q0]Cubertería Sangrapellejo refinada", additional_info = "Hechizo de 2 seg 5\n[q]Vale, es un cuchillo muy grande, pero en una cultura como la de la tribu Sangrapellejo, utilizar cualquier utensilio cuenta como una comida refinada.\n[q0]Cubertería Sangrapellejo refinada\nSe liga al recogerlo"}
MultiLanguageSpellData['mx'][93445] = {name = "Volver a Haleh", additional_info = "Rango ilimitado\nHechizo de 5 seg\n[q]Te teletransporta de vuelta a Haleh. Una carga. Solo funciona en la Cuna del Invierno."}
