MultiLanguageSpellData['mx'][127115] = {name = "[q3]Mira de fatalidad de Lord Bombington", additional_info = "Hechizo de 2 seg\nHerramientas: Llave de tuerca arcoluz , Microajustador giromático\nComponentes:\nTornillos de hierro fantasma (18), Rubí primordial (2), Espíritu de armonía\nInstructor de profesión:\nIngeniería de Pandaria (35)\nCosto:\n1\n30\n\n[q3]Mira de fatalidad de Lord Bombington\n[q2]Uso: Añade de forma permanente la mira especial de Lord Bombington a un arma de ataque a distancia, lo que hace que tu agilidad a veces aumente 47 p. durante 10 s al infligir daño con ataques a distancia.\n\n Si añades esta mira a un arma de ataque a distancia, el arma se ligará al alma. No se puede aplicar a objetos de nivel superior a 320.\nNecesitas ser de nivel 32"}
MultiLanguageSpellData['mx'][127116] = {name = "[q3]Mira de espejo", additional_info = "Hechizo de 2 seg\nHerramientas: Llave de tuerca arcoluz , Microajustador giromático\nComponentes:\nTornillos de hierro fantasma (4), Lapislázuli (2)\nInstructor de profesión:\nIngeniería de Pandaria (1)\nCosto:\n10\n\n[q3]Mira de espejo\n[q2]Uso: Añade de forma permanente una mira espejada a un arma de ataque a distancia, lo que hace que tu golpe crítico veces aumente 34 p. durante 10 s al infligir daño con ataques de largo alcance.\n\n Si añades esta mira a un arma de ataque a distancia, el arma se ligará al alma. No se puede aplicar a objetos de nivel superior a 320.\nNecesitas ser de nivel 32"}
