MultiLanguageSpellData['mx'][127127] = {name = "Terraburón G91", additional_info = "Hechizo de 2 seg\nHerramientas: Microajustador giromático\nComponentes:\nTornillos de hierro fantasma (2), Pólvora muy explosiva (2)\nInstructor de profesión:\nIngeniería de Pandaria (1)\nCosto:\n10\n\n(3)\n[q2]Uso: Inflige 688 p. de daño de Fuego a un enemigo a un máximo de 45 m, además de a cualquier enemigo a 10 m del objetivo principal. (1 Min Reutilización)\nNecesitas ser de nivel 32"}
MultiLanguageSpellData['mx'][127128] = {name = "Pistola de dragón goblin, versión 2", additional_info = "Hechizo de 3 seg\nHerramientas: Llave de tuerca arcoluz , Microajustador giromático\nComponentes:\nTornillos de hierro fantasma (3), Pólvora muy explosiva (8)\nInstructor de profesión:\nIngeniería de Pandaria (25)\nCosto:\n1\n\n[q2]Uso: Lanza un chorro de llamas, lo que inflige 48 p. de daño de Naturaleza a los objetivos en un cono de 10 m frente al taumaturgo cada 0.5 s durante 4 s.\n\n Se puede caminar mientras se lanza. (30 Seg Reutilización)\n50 cargas\nNecesitas ser de nivel 32"}
MultiLanguageSpellData['mx'][127129] = {name = "[q4]Joyatrón 4000", additional_info = "Hechizo de 2 seg\nHerramientas: Llave de tuerca arcoluz , Martillo de herrero\nComponentes:\nAcero vivo (4), Barra de trillium (4), Barra de hierro fantasma (4), Ónice bermellón (4), Jade salvaje (4), Espíritu de armonía (4)\nInstructor de profesión:\nIngeniería de Pandaria (75)\nCosto:\n3\n50\n\n[q4]Joyatrón 4000\nSe liga al recogerlo\nJuguete\n[q2]Uso: Monta el increíble Joyatrón 4000, un robot de riqueza infinita. Joyita, como le gusta que le llamen, dará un regalo aleatorio a cualquiera que hable con él, pero solo una vez cada día. Dura 10 min. (4 H Reutilización)\nRequiereIngeniería de Pandaria\n(75)"}
MultiLanguageSpellData['mx'][127130] = {name = "[q2]Gafas perforaniebla", additional_info = "Hechizo de 2 seg\nHerramientas: Llave de tuerca arcoluz , Microajustador giromático\nComponentes:\nTornillos de hierro fantasma (8), Espíritu de armonía (2)\nInstructor de profesión:\nIngeniería de Pandaria (1)\nCosto:\n10\n\n[q2]Gafas perforaniebla\nSe liga al equiparlo\nCabeza\n[q2]Equipar: Te permite ver más nodos de minería y hierbas mientras estás en Pandaria.\n[q]\"Aunque estas gafas son muy modernas, no hace falta llevarlas para recibir su beneficio especial.\""}
MultiLanguageSpellData['mx'][127131] = {name = "Yunque térmico", additional_info = "Hechizo de 2 seg\nHerramientas: Martillo de herrero\nComponentes:\nPólvora muy explosiva (8), Tornillos de hierro fantasma (6)\nInstructor de profesión:\nIngeniería de Pandaria (25)\nCosto:\n1\n\n[q2]Uso: Coloca un yunque térmico a tus pies que permite utilizar un yunque y una forja a los jugadores cercanos. Dura 5 min. (5 Min Reutilización)\n20 cargas"}
MultiLanguageSpellData['mx'][127132] = {name = "[q3]Generador de agujeros de gusano: Pandaria", additional_info = "Hechizo de 2 seg\nHerramientas: Llave de tuerca arcoluz , Microajustador giromático\nComponentes:\nBarra de trillium (12), Espíritu de armonía (2)\nInstructor de profesión:\nIngeniería de Pandaria (45)\nCosto:\n1\n75\n\n[q3]Generador de agujeros de gusano: Pandaria\nSe liga al usarlo\nJuguete\n[q2]Uso: Te teletransporta a algún lugar de Pandaria. La ubicación exacta es difícil de predecir, pero es probable que sea bastante lejos. (15 Min Reutilización)\nNecesitas ser de nivel 29\nRequiereIngeniería de Pandaria\n(1)\n[q]\"Hay una pequeña nota en un lateral: ¡Yuju!\""}
MultiLanguageSpellData['mx'][127134] = {name = "[q3]Dragonizo de hierro fantasma", additional_info = "Hechizo de 2 seg\nHerramientas: Llave de tuerca arcoluz , Martillo de herrero\nComponentes:\nPaño de lanaviento (12), Tornillos de hierro fantasma (8), Pólvora muy explosiva (4)\nComponentes opcionales:\n[] (#49)\nInstructor de profesión:\nIngeniería de Pandaria (25)\nCosto:\n1\n\n[q3]Dragonizo de hierro fantasma\nSe liga al equiparlo\nÚnico-EquipadoAbalorio\n[q0]Ranura de engranaje\n[q0]Ranura de engranaje\n[q0]Ranura de engranaje\n\n[q2]Equipar: Tus ataques tienen una probabilidad de invocar a un dragonizo de hierro fantasma para que luche por ti durante 20 s. (Probabilidad de que accione: 25%, 1m de reutilización)\nNecesitas ser de nivel 33"}
MultiLanguageSpellData['mx'][127135] = {name = "[q3]Dragonizo pandaren mecánico", additional_info = "Hechizo de 3.5 seg\nHerramientas: Llave de tuerca arcoluz , Microajustador giromático\nComponentes:\nBarra de hierro fantasma (4), Barra de trillium (6), Espíritu de armonía (2)\nInstructor de profesión:\nIngeniería de Pandaria (50)\nCosto:\n2\n\n[q3]Dragonizo pandaren mecánico\n[q2]Uso: Te enseña a invocar este compañero.\n[q2]Haz clic con el botón derecho del ratón para invocar y retirar a tu vástago.\n1 - 80 ( 80)"}
MultiLanguageSpellData['mx'][127136] = {name = "[q3]Caza mayor", additional_info = "Hechizo de 3 seg\nHerramientas: Martillo de herrero , Microajustador giromático\nComponentes:\nTornillos de hierro fantasma (12), Gatillo de pelo , Culata de nogal , Mira de espejo\nComponentes opcionales:\n[] (#49)\nInstructor de profesión:\nIngeniería de Pandaria (1)\nCosto:\n10\n\n[q3]Caza mayor\nSe liga al equiparlo\nA distancia Arma de fuego\n6 - 12 p. de daño Velocidad 3.00\n(3.0 p. de daño por segundo)\n+3 agilidad\n+6 aguante\n[q2]Aumenta tu índice de golpe crítico + 4 p.\n[q2]Aumenta tu índice de celeridad + 2 p.\n\n[q0]Ranura prismática\n[q0]Bono de ranura: + 1 agilidad\n\nDurabilidad 100 / 100\nNecesitas ser de nivel 32"}
MultiLanguageSpellData['mx'][127137] = {name = "[q3]Rifle de francotirador de trillium", additional_info = "Hechizo de 3 seg\nHerramientas: Martillo de herrero , Microajustador giromático\nComponentes:\nBarra de trillium (12), Gatillo de pelo , Espíritu de armonía , Mira de fatalidad de Lord Bombington\nInstructor de profesión:\nIngeniería de Pandaria (40)\nCosto:\n1\n50\n\n[q3]Rifle de francotirador de trillium\nSe liga al equiparlo\nA distancia Arma de fuego\n6 - 12 p. de daño Velocidad 3.00\n(3.0 p. de daño por segundo)\n+3 agilidad\n+6 aguante\n[q2]Aumenta tu índice de golpe crítico + 3 p.\n[q2]Aumenta tu índice de celeridad + 4 p.\n\n[q0]Ranura prismática\n[q0]Bono de ranura: + 0 agilidad\n\nDurabilidad 100 / 100\nNecesitas ser de nivel 35"}
MultiLanguageSpellData['mx'][127138] = {name = "[q3]Cohete de kiparium agotado", additional_info = "Hechizo de 3.5 seg\nHerramientas: Llave de tuerca arcoluz , Microajustador giromático\nComponentes:\nAcero vivo (12), Kyparita (200), Orbe de misterio (3), Pólvora muy explosiva (12), Espíritu de armonía (12), Tornillos de hierro fantasma (20)\nInstructor de profesión:\nIngeniería de Pandaria (75)\nCosto:\n3\n50\n\n[q3]Cohete de kiparium agotado\nÚnico\nMontura[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura. Cambia según tu habilidad en equitación y la zona en la que estés.\n[q2]¡El apogeo del ingenio goblin! Esta montura cambia según tu habilidad en equitación y la zona en la que estés.\n1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"Cuando la kyparita se queda sin su esencia de ámbar, se vuelve bastante resistente a la corrosión del combustible de cohete.\"\nProfesión:\nIngeniería"}
MultiLanguageSpellData['mx'][127139] = {name = "[q3]Recorremundos geosincrónico", additional_info = "Hechizo de 3.5 seg\nHerramientas: Llave de tuerca arcoluz , Microajustador giromático\nComponentes:\nAcero vivo (12), Barra de trillium (12), Espíritu de armonía (12), Tornillos de hierro fantasma (20), Orbe de misterio (3)\nInstructor de profesión:\nIngeniería de Pandaria (75)\nCosto:\n3\n50\n\n[q3]Recorremundos geosincrónico\nÚnico\nMontura[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura. Cambia según tu habilidad en equitación y la zona en la que estés.\n[q2]¡Un artilugio que rota el mundo bajo tus pies! Esta montura cambia según tu habilidad en equitación y la zona en la que estés.\n1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"Este cohete fue originalmente diseñado para acelerar la rotación del mundo, generando así noches más cortas. Los gnomos con insomnio pueden ser bastante avaros.\"\nProfesión:\nIngeniería"}
