MultiLanguageSpellData['mx'][127154] = {name = "Dragón nimbo ónice", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira a un dragón nimbo ónice que se puede montar. Es una montura voladora.\n[q]\"Los dragones nimbo ónice son conocidos por ser más agresivos y atrevidos que sus primos los dragones nimbo ónice célicos.\"\nMisión:\n¡Ataque sorpresa!\nUbicación:\nEstepas de Tong Long"}
MultiLanguageSpellData['mx'][127156] = {name = "Dragón nimbo carmesí", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira a un dragón nimbo carmesí que se puede montar. Es una montura voladora.\n[q]\"Los dragones nimbo carmesí a menudo se dejan llevar por sus alocados impulsos y se embarcan en viajes inesperados que a veces pueden duran hasta semanas.\"\nLogro:\nGloria del héroe de Pandaria\nCategoría:\nCalabozos y bandas"}
