MultiLanguageSpellData['mx'][127163] = {name = "Orbe de Poder", additional_info = "Rango ilimitado\nInstante\n[q]Sostienes el Orbe de Poder.\n Sostener el Orbe de Poder da puntos de victoria a tu equipo.Reduce la sanación recibida un 0%."}
MultiLanguageSpellData['mx'][127164] = {name = "Dragón nimbo dorado célico", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira a un dragón nimbo dorado célico que se puede montar. Es una montura voladora.\n[q]\"Calidez y esperanza emanan de esta gran criatura, que brilla como la luz del amanecer sobre las montañas.\"\nVendedor:\nTejedor de niebla Ku\nZona:\nIsla Intemporal\nEmperador Shaohao - Exaltado"}
MultiLanguageSpellData['mx'][127165] = {name = "Yu'lei, hija de Jade", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira a Yu'lei, hija de Jade. Es una montura voladora.\n[q]\"Calidez y sabiduría emanan de esta gran criatura, que brilla como la luz de la luna que pasa por el jade más fino.\"\nVendedor:\nTejedora de niebla Xia\nZona:\nIsla Intemporal\nCosto:\n5000"}
MultiLanguageSpellData['mx'][127169] = {name = "Dragón nimbo azur célico", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira a un dragón nimbo azur célico que se puede montar. Es una montura voladora.\n[q]\"Calidez y serenidad emanan de esta gran criatura, que brilla como el cielo más nublado de una tarde de verano.\"\nLogro:\nSeñor de las riendas\nCategoría:\nMonturas"}
MultiLanguageSpellData['mx'][127170] = {name = "Dragón nimbo astral", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira a un dragón nimbo astral que se puede montar. Es una montura voladora.\n[q]\"Se cree que los dragones nimbo astrales poseen la respuesta a algunos de los misterios más grandes de la vida. Es una lástima que no puedan hablar.\"\nBotín:\nAlijo de energía pura"}
