MultiLanguageSpellData['mx'][127174] = {name = "Grulla de montar azur", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira a una grulla de montar azur.\n[q]\"La grulla majestuosa es un valioso amigo de los pandaren.\"\nVendedor:\nJaluu el Generoso\nZona:\nValle de la Flor Eterna\nLoto Dorado - Exaltado\nCosto:\n500"}
