MultiLanguageSpellData['mx'][127176] = {name = "Grulla de montar dorada", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira a una grulla de montar dorada.\n[q]\"La grulla es un símbolo de sabiduría y nobleza, su capacidad de llevarnos a los cielos es casi un milagro. -Jaluu el Generoso\"\nVendedor:\nJaluu el Generoso\nZona:\nValle de la Flor Eterna\nLoto Dorado - Exaltado\nCosto:\n2500"}
