MultiLanguageSpellData['mx'][145411] = {name = "Enfurecer", additional_info = "Alcance de ataques cuerpo a cuerpo\nHechizo de 1 seg\n[q]Se enfurece, lo que lo libera de los efectos de reducción de movimiento y pérdida de control y lo vuelve inmune a ellos. Aumenta la velocidad de movimiento un 100%, lo que aumenta el daño infligido un 150% y la velocidad de ataque un 25% durante 10 s."}
MultiLanguageSpellData['mx'][145412] = {name = "Llamar a Rapidín", additional_info = "Instante\n[q]Invoca a Rapidín."}
MultiLanguageSpellData['mx'][145413] = {name = "Mutilar con mano izquierda", additional_info = "Alcance de ataques cuerpo a cuerpo\nInstante\n[q]Ataca instantáneamente con las dos armas, lo que inflige un ([115% of Attack Power])% de daño con arma con cada una. Otorga 2 p. de combo."}
MultiLanguageSpellData['mx'][145414] = {name = "Mutilar", additional_info = "Alcance de ataques cuerpo a cuerpo\nInstante\n[q]Ataca instantáneamente con las dos armas, lo que inflige un ([115% of Attack Power])% de daño con arma con cada una. Otorga 2 p. de combo."}
MultiLanguageSpellData['mx'][145415] = {name = "Mutilar", additional_info = "{55 p. de energía} {Alcance de ataques cuerpo a cuerpo}\nInstante\n[q]Ataca instantáneamente con las dos armas, lo que inflige un ([115% of Attack Power])% de daño con arma con cada una. Otorga 0 p. de combo."}
MultiLanguageSpellData['mx'][145416] = {name = "Envenenar", additional_info = "{35 p. de energía} {Alcance de ataques cuerpo a cuerpo}\nInstante\n[q]Remate que inflige daño de Naturaleza instantáneo proporcional a la cantidad de puntos de combo en el objetivo. Tras el ataque Envenenar, tu probabilidad de aplicar un veneno aumenta un 15% durante 1 s más 1 s extra por cada punto de combo."}
MultiLanguageSpellData['mx'][145417] = {name = "Ruptura", additional_info = "{25 p. de energía} {Alcance de ataques cuerpo a cuerpo}\nInstante\n[q]Remate que inflige daño en el tiempo. Se prolonga e inflige más daño por cada punto de combo."}
MultiLanguageSpellData['mx'][145418] = {name = "Hacer picadillo", additional_info = "{25 p. de energía} {Alcance de 100 m}\nInstante\n[q]Remate que consume los puntos de combo en cualquier objetivo cercano para aumentar la velocidad de ataque cuerpo a cuerpo un 40%. Se prolonga por cada punto de combo."}
MultiLanguageSpellData['mx'][145419] = {name = "Veneno mortal", additional_info = "Alcance de 100 m\nInstante\n[q]Las armas envenenadas tienen una probabilidad de infligir 200 p. de daño de Naturaleza a un objetivo que ya esté afectado por Veneno mortal."}
MultiLanguageSpellData['mx'][145420] = {name = "Veneno mortal", additional_info = "Alcance de 100 m\nInstante\n[q]Cubre tus armas con un veneno letal que dura 1 h. Cada golpe tiene un 30% de probabilidad de envenenar al enemigo e infligir [([11.374% of Attack Power]) * 12 / 2] p. de daño de naturaleza durante 12 s. Las siguientes aplicaciones del veneno infligirán ([8.14% of Attack Power]) p. de daño de naturaleza de forma instantánea."}
MultiLanguageSpellData['mx'][145421] = {name = "Veneno mortal", additional_info = "Hechizo de 3 seg\nRequiere Arma cuerpo a cuerpo de una mano\n[q]Cubre tus armas con un veneno letal que dura 12 s. Cada golpe tiene un 30% de probabilidad de envenenar al enemigo e infligir 1600 p. de daño de Naturaleza durante 12 s. Las siguientes aplicaciones del veneno infligirán 200 p. de daño de Naturaleza de forma instantánea.\n(Probabilidad de que accione: 30%)"}
MultiLanguageSpellData['mx'][145422] = {name = "Abanico de cuchillos", additional_info = "35 p. de energía\nInstante\n[q]Giras instantáneamente desatando una lluvia de cuchillos que se lanzan a todos los objetivos en un radio de 10 m e infligen 1005 p. de daño físico. Este ataque tiene una probabilidad de aplicar tus venenos activos al índice habitual. Otorga 1005 p. de combo si golpea a tu objetivo de combo actual."}
MultiLanguageSpellData['mx'][145423] = {name = "Sigilo", additional_info = "{Instante} {6 seg de reutilización}\n[q]Te oculta entre las sombras, lo que te permite acechar a enemigos sin ser visto. Dura hasta que se cancela."}
MultiLanguageSpellData['mx'][145424] = {name = "Golpe bajo", additional_info = "{40 p. de energía} {Alcance de 10 m}\nInstante\nRequiere Sigilo\n[q]Aturde al objetivo durante 4 s. Tienes que estar en sigilo. Otorga 2 p. de combo."}
MultiLanguageSpellData['mx'][145425] = {name = "Paso de las Sombras", additional_info = "Alcance de 100 m\nInstante\n[q]Camina entre las sombras para aparecer detrás de tu objetivo y obtener un 70% más de velocidad de movimiento durante 2 s. [ Sutileza : Si ya conoces Paso de las Sombras , en cambio obtienes 1 carga más de Paso de las Sombras ]"}
MultiLanguageSpellData['mx'][145426] = {name = "Paso de las Sombras", additional_info = "Alcance de 25 m\n{Instante} {24 seg de reutilización}\n[q]Provoca que des un paso en las sombras y reaparezcas detrás de un objetivo. Tu velocidad de movimiento aumenta un 70% durante los 2 s siguientes."}
MultiLanguageSpellData['mx'][145427] = {name = "Patada", additional_info = "Alcance de ataques cuerpo a cuerpo\n{Instante} {15 seg de reutilización}\n[q]Una patada rápida que interrumpe el lanzamiento de hechizos y evita que se puedan lanzar hechizos de esa misma escuela durante 2 s."}
