MultiLanguageSpellData['mx'][145434] = {name = "Explosión Arcana", additional_info = "{8% del maná base} {Alcance de 40 m}\nHechizo de 2 seg\n[q]Golpea al objetivo con energía, lo que inflige ([66.519% of Spell Power]) p. de daño Arcano. Genera una carga Arcana.\n\n El daño de Explosión Arcana aumenta un 60 % por carga Arcana y su coste de maná aumenta un 90 % por carga Arcana."}
MultiLanguageSpellData['mx'][145435] = {name = "Misiles Arcanos", additional_info = "Alcance de 60 m\nCanalizado\n[q]Solo se puede lanzar cuando tienes Lanzamiento libre.\n\n Lanza cinco olas de Misiles arcanos al enemigo durante 2.5 s y causa un total de [5 * ([52.6% of Spell Power])] p. de daño arcano."}
MultiLanguageSpellData['mx'][145436] = {name = "Misiles Arcanos", additional_info = "Alcance de 40 m\nCanalizado (Hechizo de 2 seg)\n[q]Lanza contra el enemigo cinco oleadas de Misiles Arcanos durante 2.5 s, lo que inflige ([52.6% of Spell Power]) p. de daño Arcano por oleada. Genera una carga Arcana.\n\n El daño de Misiles Arcanos aumenta un 60 % por carga Arcana."}
MultiLanguageSpellData['mx'][145437] = {name = "Tromba Arcana", additional_info = "{4% del maná base} {Alcance de 40 m}\n{Instante} {3 seg de reutilización}\n[q]Lanza descargas de energía Arcana contra el objetivo enemigo, lo que inflige 1006 p. de daño Arcano. También inflige un 40% de daño a 4 objetivos cercanos extra. Consume todas las cargas Arcanas.\n\n El daño de Tromba Arcana aumenta un 60 % por carga Arcana."}
