MultiLanguageSpellData['mx'][148266] = {name = "Glifo de Esqueleto", additional_info = "Hechizo de 2 seg\nHerramientas: Juego de caligrafía de virtuoso\nComponentes:\nPapiro ligero , Tinta de medianoche (3)\nProfesión:\nInscripción (75)\nDescubrimiento:\nInvestigación: Tinta de medianoche\n\nClases: Caballero de la muerte\n[q2]Uso: Te enseña permanentemente este glifo.\n\nTu hechizo Levantar a los muertos invoca un esqueleto en vez de un necrófago.\n\n [ Eructador de lodo : No funciona cuando se ha usado un talento para convertirlo en un eructador de lodo ] Exclusivo con: Glifo de Geist\nNecesitas ser de nivel 11"}
MultiLanguageSpellData['mx'][148270] = {name = "Glifo de Elemental desatado", additional_info = "Hechizo de 2 seg\nHerramientas: Juego de caligrafía de virtuoso\nComponentes:\nPapiro ligero , Tinta de fuego de jade (3)\nProfesión:\nInscripción (150)\nDescubrimiento:\nInvestigación: Tinta de fuego de jade\n\nClases: Mago\n[q2]Uso: Te enseña permanentemente este glifo.\n\nTu elemental de agua se reemplaza con un elemental de agua desatado. Exclusivo con: Glifo de Evaporación Glifo de las mareas Glifo de Estela de la Tormenta Glifo de profundidades oscuras Glifo de furia humeante Glifo de olas frías\nNecesitas ser de nivel 11"}
MultiLanguageSpellData['mx'][148271] = {name = "Glifo de Evaporación", additional_info = "Hechizo de 2 seg\nHerramientas: Juego de caligrafía de virtuoso\nComponentes:\nPapiro ligero , Tinta de león (3)\nProfesión:\nInscripción (100)\nDescubrimiento:\nInvestigación: Tinta de león\n\nClases: Mago\n[q2]Uso: Te enseña permanentemente este glifo.\n\nReduce el tamaño de tu elemental de agua un 15%. Exclusivo con: Glifo de Elemental desatado Glifo de las mareas Glifo de Estela de la Tormenta Glifo de profundidades oscuras Glifo de furia humeante Glifo de olas frías\nNecesitas ser de nivel 11"}
MultiLanguageSpellData['mx'][148274] = {name = "Glifo de Pilar de luz", additional_info = "Hechizo de 2 seg\nHerramientas: Juego de caligrafía de virtuoso\nComponentes:\nPapiro ligero , Tinta onírica (3)\nProfesión:\nInscripción de Pandaria (1)\nDescubrimiento:\nInvestigación: Tinta onírica\n\nClases: Paladín\n[q2]Uso: Te enseña permanentemente este glifo.\n\nLas sanaciones críticas con Choque Sagrado a otros jugadores muestran un pequeño pilar de luz brevemente en su ubicación.\nNecesitas ser de nivel 11"}
MultiLanguageSpellData['mx'][148275] = {name = "Glifo de ángeles", additional_info = "Hechizo de 2 seg\nHerramientas: Juego de caligrafía de virtuoso\nComponentes:\nPapiro ligero , Tinta del mar (3)\nBotín:\nCriaturas del mundo\n\nClases: Sacerdote\n[q2]Uso: Te enseña permanentemente este glifo.\n\nSi lanzas hechizos de sanación, tienes una probabilidad de conseguir alas angelicales. (Probabilidad de que accione: 15%)\nNecesitas ser de nivel 11"}
MultiLanguageSpellData['mx'][148276] = {name = "Glifo del Sha", additional_info = "Hechizo de 2 seg 2\nHerramientas: Juego de caligrafía de virtuoso\nComponentes:\nPapiro ligero , Tinta etérea (3)\nProfesión:\nInscripción de Terrallende (1)\nDescubrimiento:\nInvestigación: Tinta etérea\n\n\nClases: Sacerdote\n[q2]Uso: Te enseña permanentemente este glifo.\n\nTransforma a tu maligno de las Sombras en una bestia sha. Exclusivo con: Glifo del engendro de luz Glifo del ser del Vacío\nNecesitas ser de nivel 11"}
MultiLanguageSpellData['mx'][148278] = {name = "Glifo de Himnos inspirados", additional_info = "Hechizo de 2 seg\nHerramientas: Juego de caligrafía de virtuoso\nComponentes:\nPapiro ligero , Tinta de resplandor lunar (3)\nProfesión:\nInscripción (25)\nDescubrimiento:\nInvestigación: Tinta de resplandor lunar\n\nClases: Sacerdote\n[q2]Uso: Te enseña permanentemente este glifo.\n\nMientras canalices hechizos de himnos, un espíritu aparecerá sobre ti.\nNecesitas ser de nivel 11"}
MultiLanguageSpellData['mx'][148281] = {name = "Glifo de Espìritus de raptores", additional_info = "Hechizo de 2 seg\nHerramientas: Juego de caligrafía de virtuoso\nComponentes:\nPapiro ligero , Tinta de león (3)\nProfesión:\nInscripción (100)\nDescubrimiento:\nInvestigación: Tinta de león\n\nGlifo de Raptores espirituales\nClases: Chamán\n[q2]Uso: Te enseña permanentemente este glifo.\n\nTus espíritus de lobo se reemplazan por espíritus de raptores.\nNecesitas ser de nivel 11"}
