MultiLanguageSpellData['mx'][161386] = {name = "Aprendiendo", additional_info = "Hechizo de 3 seg\n[q]Proporciona los planos necesarios para construir la Forja en tu fortaleza.\n\n Level 1\nPermite la producción de objetos y pedidos de herrería.\n\n Level 2\nPermite que los seguidores con la característica de herrería trabajen aquí, lo que otorga un bonus único. También permite hasta 14 pedidos por vez.\n\n Level 3\nDesbloquea misiones de herrería y permite hasta 21 pedidos a la vez."}
MultiLanguageSpellData['mx'][161387] = {name = "Aprendiendo", additional_info = "Hechizo de 3 seg\n[q]Proporciona los planos necesarios para construir un Laboratorio de alquimia en tu fortaleza.\n\n Level 1\nPermite la producción de objetos y pedidos de alquimia.\n\n Level 2\nPermite que los seguidores con la característica de alquimia trabajen aquí, lo que otorga un bonus único. También permite hasta 14 pedidos por vez.\n\n Level 3\nDesbloquea misiones de alquimia y permite hasta 21 pedidos a la vez."}
MultiLanguageSpellData['mx'][161388] = {name = "Aprendiendo", additional_info = "Hechizo de 3 seg\n[q]Proporciona los planos necesarios para construir un edificio de Peletería en tu fortaleza.\n\n Level 1\nPermite la producción de objetos y pedidos de peletería.\n\n Level 2\nPermite que los seguidores con la característica de peletería trabajen aquí, lo que otorga un bonus único. También permite hasta 14 pedidos por vez.\n\n Level 3\nDesbloquea misiones de peletería y permite hasta 21 pedidos a la vez."}
MultiLanguageSpellData['mx'][161389] = {name = "Aprendiendo", additional_info = "Hechizo de 3 seg\n[q]Proporciona los planos necesarios para construir un estudio del Encantador en tu fortaleza.\n\n Level 1\nPermite la producción de objetos de encantamiento y permite que los no encantadores desencanten objetos. Además, permite la producción de pedidos.\n\n Level 2\nPermite que los seguidores con la característica de encantamiento trabajen aquí, lo que otorga un bonus único. También permite hasta 14 pedidos por vez.\n\n Level 3\nDesbloquea misiones de encantamiento y permite hasta 21 pedidos a la vez."}
MultiLanguageSpellData['mx'][161390] = {name = "Aprendiendo", additional_info = "Hechizo de 3 seg\n[q]Proporciona los planos necesarios para construir un Emporio de sastrería en tu fortaleza.\n\n Level 1\nPermite la producción de objetos y pedidos de sastrería.\n\n Level 2\nPermite que los seguidores con la característica de sastrería trabajen aquí, lo que otorga una bonificación única. También permite hasta 14 pedidos por vez.\n\n Level 3\nDesbloquea misiones de sastrería y permite hasta 21 pedidos a la vez."}
MultiLanguageSpellData['mx'][161391] = {name = "Aprendiendo", additional_info = "Hechizo de 3 seg\n[q]Proporciona los planos necesarios para construir un Scriptorium en tu fortaleza.\n\n Level 1\nPermite la producción de objetos y pedidos de inscripción.\n\n Level 2\nPermite que los seguidores con la característica de inscripción trabajen aquí, lo que otorga una bonificación única. También permite hasta 14 pedidos por vez.\n\n Level 3\nDesbloquea misiones de inscripción y permite hasta 21 pedidos a la vez."}
MultiLanguageSpellData['mx'][161392] = {name = "Aprendiendo", additional_info = "Hechizo de 3 seg\n[q]Proporciona los planos necesarios para construir una Boutique de gemas en tu fortaleza.\n\n Level 1\nPermite la producción de objetos y pedidos de joyería.\n\n Level 2\nPermite que los seguidores con la característica de joyería trabajen aquí, lo que otorga un bonus único. También permite hasta 14 pedidos por vez.\n\n Level 3\nDesbloquea misiones de joyería y permite hasta 21 pedidos a la vez."}
