MultiLanguageSpellData['mx'][162001] = {name = "Aprendiendo", additional_info = "Hechizo de 3 seg\n[q]Proporciona los planos necesarios para construir un Búnker enano en tu fortaleza.\n\n Level 1\nDuplica la posibilidad de que tus recompensas de misiones obtengan una mejora de bonificación poco común o épica y aumenta la potencia de la mejora. Permite recolectar restos de armadura de los clanes orcos de Draenor para transfigurar la armadura.\n\n Level 2\nAbre pedidos de armas y armadura de seguidor a cambio de recursos de la fortaleza. Además, desbloquea nuevas armaduras de transfiguración.\n\n Level 3\nOtorga 1 de tus 3 sellos del destino inevitable (lanzamiento de dados bonus de banda) sin costo, cada semana."}
MultiLanguageSpellData['mx'][162002] = {name = "Aprendiendo", additional_info = "Hechizo de 3 seg\n[q]Proporciona los planos necesarios para mejorar tu Búnker enano al nivel 2.\n\n Level 1\nDuplica la posibilidad de que tus recompensas de misiones obtengan una mejora de bonificación poco común o épica y aumenta la potencia de la mejora. Permite recolectar restos de armadura de los clanes orcos de Draenor para transfigurar la armadura.\n\n Level 2\nAbre pedidos de armas y armadura de seguidor a cambio de recursos de la fortaleza. Además, desbloquea nuevas armaduras de transfiguración.\n\n Level 3\nOtorga 1 de tus 3 sellos del destino inevitable (lanzamiento de dados bonus de banda) sin costo, cada semana."}
MultiLanguageSpellData['mx'][162003] = {name = "Aprendiendo", additional_info = "Hechizo de 3 seg\n[q]Proporciona los planos necesarios para mejorar tu Búnker enano al nivel 3.\n\n Level 1\nDuplica la posibilidad de que tus recompensas de misiones obtengan una mejora de bonificación poco común o épica y aumenta la potencia de la mejora. Permite recolectar restos de armadura de los clanes orcos de Draenor para transfigurar la armadura.\n\n Level 2\nAbre pedidos de armas y armadura de seguidor a cambio de recursos de la fortaleza. Además, desbloquea nuevas armaduras de transfiguración.\n\n Level 3\nOtorga 1 de tus 3 sellos del destino inevitable (lanzamiento de dados bonus de banda) sin costo, cada semana."}
MultiLanguageSpellData['mx'][162004] = {name = "Vuelo", additional_info = nil}
MultiLanguageSpellData['mx'][162005] = {name = "Aprendiendo", additional_info = "Hechizo de 3 seg\n[q]Proporciona los planos necesarios para construir una granja en tu fortaleza.\n\n Level 1\nTe permite capturar uñagrietas, elekk, lobos y talbuk para obtener cuero y pieles. Usado para fórmulas de peletería y sastrería.\n\n Level 2\nTe permite capturar jabalíes y bestias de río para obtener carnes poco comunes, usadas para cocinar comidas súper poderosas.\n\n Level 3\nTe permite capturar bestias de élite para recolectar sangre salvaje, usada en todas las armaduras y armas épicas."}
MultiLanguageSpellData['mx'][162006] = {name = "Aprendiendo", additional_info = "Hechizo de 3 seg\n[q]Proporciona los planos necesarios para mejorar tu granja al nivel 2.\n\n Level 1\nTe permite capturar uñagrietas, elekk, lobos y talbuk para obtener cuero y pieles. Usado para fórmulas de peletería y sastrería.\n\n Level 2\nTe permite capturar jabalíes y bestias de río para obtener carnes poco comunes, usadas para cocinar comidas súper poderosas.\n\n Level 3\nTe permite capturar bestias de élite para recolectar sangre salvaje, usada en todas las armaduras y armas épicas."}
MultiLanguageSpellData['mx'][162007] = {name = "Aprendiendo", additional_info = "Hechizo de 3 seg\n[q]Proporciona los planos necesarios para mejorar tu Cuartel al nivel 2.\n\n Level 1\nDesbloquea misiones de patrulla. Las misiones de patrulla otorgan recompensas de experiencia a seguidores más altas de lo normal.\n\n Level 2\nPermite que un seguidor con la característica de guardaespaldas te acompañe como guardián en zonas de Draenor.\n\n Level 3\nAumenta el límite de seguidores a 5 y otorga acceso a los guardias y estandartes raciales."}
MultiLanguageSpellData['mx'][162008] = {name = "Aprendiendo", additional_info = "Hechizo de 3 seg\n[q]Proporciona los planos necesarios para mejorar tu Cuartel al nivel 3.\n\n Level 1\nDesbloquea misiones de patrulla. Las misiones de patrulla otorgan recompensas de experiencia a seguidores más altas de lo normal.\n\n Level 2\nPermite que un seguidor con la característica de guardaespaldas te acompañe como guardián en zonas de Draenor.\n\n Level 3\nAumenta el límite de seguidores a 5 y otorga acceso a los guardias y estandartes raciales."}
MultiLanguageSpellData['mx'][162009] = {name = "Aprendiendo", additional_info = "Hechizo de 3 seg\n[q]Proporciona los planos necesarios para mejorar tu Forja al nivel 2.\n\n Level 1\nPermite la producción de objetos y pedidos de herrería.\n\n Level 2\nPermite que los seguidores con la característica de herrería trabajen aquí, lo que otorga un bonus único. También permite hasta 14 pedidos por vez.\n\n Level 3\nDesbloquea misiones de herrería y permite hasta 21 pedidos a la vez."}
