MultiLanguageSpellData['mx'][162033] = {name = "Aprendiendo", additional_info = "Hechizo de 3 seg\n[q]Proporciona los planos necesarios para construir un Sagrario del Gladiador en tu fortaleza.\n\n Level 1\nAumenta tu regeneración fuera de combate en zonas al aire libre de Draenor y permite recolectar huesos rotos de jugadores enemigos derrotados (se usan para el Tributo al Conquistador).\n\n Level 2\nPermite una caída segura y respiración bajo el agua en zonas al aire libre de Draenor. También permite la serie de misiones Némesis para derrotar a jugadores enemigos de razas específicas.\n\n Level 3\nSi tu salud se encuentra debajo del 35%, todo el daño recibido se reduce un 50% en zonas al aire libre de Draenor. Otorga acceso al torneo de gladiadores en el coliseo Gran Magullador."}
MultiLanguageSpellData['mx'][162034] = {name = "Aprendiendo", additional_info = "Hechizo de 3 seg\n[q]Proporciona los planos necesarios para mejorar tu Sagrario del Gladiador al nivel 2.\n\n Level 1\nAumenta tu regeneración fuera de combate en zonas al aire libre de Draenor y permite recolectar huesos rotos de jugadores enemigos derrotados (se usan para el Tributo al Conquistador).\n\n Level 2\nPermite una caída segura y respiración bajo el agua en zonas al aire libre de Draenor. También permite la serie de misiones Némesis para derrotar a jugadores enemigos de razas específicas.\n\n Level 3\nSi tu salud se encuentra debajo del 35%, todo el daño recibido se reduce un 50% en zonas al aire libre de Draenor. Otorga acceso al torneo de gladiadores en el coliseo Gran Magullador."}
MultiLanguageSpellData['mx'][162035] = {name = "Aprendiendo", additional_info = "Hechizo de 3 seg\n[q]Proporciona los planos necesarios para mejorar tu Sagrario del Gladiador al nivel 3.\n\n Level 1\nAumenta tu regeneración fuera de combate en zonas al aire libre de Draenor y permite recolectar huesos rotos de jugadores enemigos derrotados (se usan para el Tributo al Conquistador).\n\n Level 2\nPermite una caída segura y respiración bajo el agua en zonas al aire libre de Draenor. También permite la serie de misiones Némesis para derrotar a jugadores enemigos de razas específicas.\n\n Level 3\nSi tu salud se encuentra debajo del 35%, todo el daño recibido se reduce un 50% en zonas al aire libre de Draenor. Otorga acceso al torneo de gladiadores en el coliseo Gran Magullador."}
MultiLanguageSpellData['mx'][162036] = {name = "Aprendiendo", additional_info = "Hechizo de 3 seg\n[q]Proporciona los planos necesarios para construir un Almacén en tu fortaleza.\n\n Level 1\nPermite acceder a tu banco personal. Aumenta en 5 el número total de pedidos activos para todos los edificios.\n\n Level 2\nPermite acceder al banco de tu hermandad.\n\n Level 3\nPermite acceder a un comerciante etéreo para depósito del vacío y transfigurar. Aumenta 15 veces el número total de pedidos activos para todos los edificios."}
MultiLanguageSpellData['mx'][162037] = {name = "Aprendiendo", additional_info = "Hechizo de 3 seg\n[q]Proporciona los planos necesarios para mejorar tu Almacén al nivel 2.\n\n Level 1\nPermite acceder a tu banco personal. Aumenta en 5 el número total de pedidos activos para todos los edificios.\n\n Level 2\nPermite acceder al banco de tu hermandad.\n\n Level 3\nPermite acceder a un comerciante etéreo para depósito del vacío y transfigurar. Aumenta 15 veces el número total de pedidos activos para todos los edificios."}
