MultiLanguageSpellData['mx'][162042] = {name = "Aprendiendo", additional_info = "Hechizo de 3 seg\n[q]Proporciona los planos necesarios para mejorar tu Sala de las fieras al nivel 2.\n\n Level 1\nAtrae mascotas de élite con las que puedes combatir a cambio de recompensas. También permite que 5 de tus mascotas de duelo anden por tu fortaleza.\n\n Level 2\nAumenta las probabilidades de trampa y reduce el tiempo de reutilización de Revivir mascotas mientras estás en Draenor. Ahora, hasta 10 de tus mascotas pueden andar por tu fortaleza.\n\n Level 3\nCada día desbloquea una mascota de duelo con recompensas de mascota únicas."}
MultiLanguageSpellData['mx'][162043] = {name = "Aprendiendo", additional_info = "Hechizo de 3 seg\n[q]Proporciona los planos necesarios para mejorar tu Sala de las fieras al nivel 3.\n\n Level 1\nAtrae mascotas de élite con las que puedes combatir a cambio de recompensas. También permite que 5 de tus mascotas de duelo anden por tu fortaleza.\n\n Level 2\nAumenta las probabilidades de trampa y reduce el tiempo de reutilización de Revivir mascotas mientras estás en Draenor. Ahora, hasta 10 de tus mascotas pueden andar por tu fortaleza.\n\n Level 3\nCada día desbloquea una mascota de duelo con recompensas de mascota únicas."}
MultiLanguageSpellData['mx'][162044] = {name = "Aprendiendo", additional_info = "Hechizo de 3 seg\n[q]Proporciona los planos necesarios para mejorar tu Excavación Caída de la Luna al nivel 2.\n\n Level 1\nPermite a los jugadores extraer piedra draénica de nodos minerales en Draenor. La piedra draénica puede convertirse en pedidos para minerales de Draenor.\n\n Level 2\nPermite que los seguidores con la característica de minería trabajen aquí, lo que otorga una bonificación única. Además, abre un pozo de mina nuevo que permite el acceso a nodos minerales extra y hasta 14 pedidos de una vez.\n\n Level 3\nUn último pozo de mina permite el acceso a nodos minerales ricos. También, los guardias de la fortaleza patrullarán tu mina, manteniendo alejados a los goren hostiles. Además, permite hasta 21 pedidos a la vez."}
MultiLanguageSpellData['mx'][162045] = {name = "Aprendiendo", additional_info = "Hechizo de 3 seg\n[q]Proporciona los planos necesarios para mejorar tu Excavación Caída de la Luna al nivel 3.\n\n Level 1\nPermite a los jugadores extraer piedra draénica de nodos minerales en Draenor. La piedra draénica puede convertirse en pedidos para minerales de Draenor.\n\n Level 2\nPermite que los seguidores con la característica de minería trabajen aquí, lo que otorga una bonificación única. Además, abre un pozo de mina nuevo que permite el acceso a nodos minerales extra y hasta 14 pedidos de una vez.\n\n Level 3\nUn último pozo de mina permite el acceso a nodos minerales ricos. También, los guardias de la fortaleza patrullarán tu mina, manteniendo alejados a los goren hostiles. Además, permite hasta 21 pedidos a la vez."}
MultiLanguageSpellData['mx'][162046] = {name = "Aprendiendo", additional_info = "Hechizo de 3 seg\n[q]Proporciona los planos necesarios para mejorar tu Herbario al nivel 2.\n\n Level 1\nHace que las semillas draénicas se transformen en hierbas cada día y haya nodos de herboristería disponibles en el jardín.\n\n Level 2\nPermite que los seguidores con la característica de herboristería trabajen aquí, lo que les otorga una bonificación única. Además, aumenta la cantidad de hierbas que pueden recolectarse en el jardín y permite hasta 14 pedidos a la vez.\n\n Level 3\nHace crecer un árbol de frutos de Draenor único en tu jardín que da beneficios de comida. Además, permite hasta 21 pedidos a la vez."}
MultiLanguageSpellData['mx'][162047] = {name = "Aprendiendo", additional_info = "Hechizo de 3 seg\n[q]Proporciona los planos necesarios para mejorar tu Herbario al nivel 3.\n\n Level 1\nHace que las semillas draénicas se transformen en hierbas cada día y haya nodos de herboristería disponibles en el jardín.\n\n Level 2\nPermite que los seguidores con la característica de herboristería trabajen aquí, lo que les otorga una bonificación única. Además, aumenta la cantidad de hierbas que pueden recolectarse en el jardín y permite hasta 14 pedidos a la vez.\n\n Level 3\nHace crecer un árbol de frutos de Draenor único en tu jardín que da beneficios de comida. Además, permite hasta 21 pedidos a la vez."}
