MultiLanguageSpellData['mx'][162195] = {name = "[q4]Gafas mecanizadas cibergenéticas", additional_info = "Hechizo de 2 seg\nHerramientas: Microajustador giromático\nComponentes:\nPiezas de resorte de engranaje (100)\nComponentes opcionales:\n[] (#50) , Piñón de bloqueo Grasenlace (#238)\nVendedor:\nNik Aroacero\nZona:\nLanza de Guerra\nCosto:\n1\n\n[q4]Gafas mecanizadas cibergenéticas\nSe liga al equiparlo\nÚnico-Equipado: Fabricado - Warlords (3)Cabeza Malla\n8 armadura\n+5 [Agilidad o Intelecto]+7 aguante\nDurabilidad 100 / 100\n[q2]Uso: Permite ver a lo lejos.\nNecesitas ser de nivel 35\nRequiereIngeniería de Draenor\n(1)"}
MultiLanguageSpellData['mx'][162196] = {name = "[q4]Gafas mecanizadas para visión nocturna", additional_info = "Hechizo de 2 seg\nHerramientas: Llave de tuerca arcoluz , Microajustador giromático\nComponentes:\nPiezas de resorte de engranaje (100)\nComponentes opcionales:\n[] (#50) , Piñón de bloqueo Grasenlace (#238)\nVendedor:\nNik Aroacero\nZona:\nLanza de Guerra\nCosto:\n1\n\n[q4]Gafas mecanizadas para visión nocturna\nSe liga al equiparlo\nÚnico-Equipado: Fabricado - Warlords (3)Cabeza Cuero\n6 armadura\n+5 [Agilidad o Intelecto]+7 aguante\nDurabilidad 100 / 100\n[q2]Uso: Permite ver a lo lejos.\nNecesitas ser de nivel 35\nRequiereIngeniería de Draenor\n(1)"}
MultiLanguageSpellData['mx'][162197] = {name = "[q4]Gafas mecanizadas de plasma", additional_info = "Hechizo de 2 seg\nHerramientas: Microajustador giromático\nComponentes:\nPiezas de resorte de engranaje (100)\nComponentes opcionales:\n[] (#50) , Piñón de bloqueo Grasenlace (#238)\nVendedor:\nNik Aroacero\nZona:\nLanza de Guerra\nCosto:\n1\n\n[q4]Gafas mecanizadas de plasma\nSe liga al equiparlo\nÚnico-Equipado: Fabricado - Warlords (3)Cabeza Tela\n3 armadura\n+5 intelecto\n+7 aguante\nDurabilidad 100 / 100\n[q2]Uso: Permite ver a lo lejos.\nNecesitas ser de nivel 35\nRequiereIngeniería de Draenor\n(1)"}
MultiLanguageSpellData['mx'][162198] = {name = "[q4]Gafas mecanizadas rajaguardia", additional_info = "Hechizo de 2 seg\nHerramientas: Microajustador giromático\nComponentes:\nPiezas de resorte de engranaje (100)\nComponentes opcionales:\n[] (#50) , Piñón de bloqueo Grasenlace (#238)\nVendedor:\nNik Aroacero\nZona:\nLanza de Guerra\nCosto:\n1\n\n[q4]Gafas mecanizadas rajaguardia\nSe liga al equiparlo\nÚnico-Equipado: Fabricado - Warlords (3)Cabeza Placas\n13 armadura\n+5 [Fuerza o Intelecto]+7 aguante\nDurabilidad 100 / 100\n[q2]Uso: Permite ver a lo lejos.\nNecesitas ser de nivel 35\nRequiereIngeniería de Draenor\n(1)"}
MultiLanguageSpellData['mx'][162199] = {name = "[q4]Trituradora de Hierrotriturado", additional_info = "Hechizo de 3 seg\nHerramientas: Microajustador giromático\nSin profesión:\nNecesita obras de ingeniería nivel 3\nComponentes:\nPiezas de resorte de engranaje (100)\nComponentes opcionales:\n[] (#50) , Activador de hierro genuino (#239)\nVendedor:\nNik Aroacero\nZona:\nLanza de Guerra\nCosto:\n1\n\n[q4]Trituradora de Hierrotriturado\nSe liga al equiparlo\nÚnico-Equipado: Fabricado - Warlords (3)A distancia Arma de fuego\n7 - 13 p. de daño Velocidad 3.00\n(3.3 p. de daño por segundo)\n+5 agilidad\n+7 aguante\nDurabilidad 120 / 120\nNecesitas ser de nivel 35\n[q]\"Para los ingenieros, una obra de arte. Para los cazadores, una herramienta para el arte de matar.\""}
MultiLanguageSpellData['mx'][162202] = {name = "[q3]Machacamisiles de Oglethorpe", additional_info = "Hechizo de 2 seg\nHerramientas: Microajustador giromático\nSin profesión:\nNecesita obras de ingeniería nivel 2\nComponentes:\nPiezas de resorte de engranaje (20)\nVendedor:\nNik Aroacero\nZona:\nLanza de Guerra\nCosto:\n1\n\n[q3]Machacamisiles de Oglethorpe\n[q2]Uso: Añade de forma permanente un dispositivo especial a un arma de ataque a distancia, lo que a veces aumenta 115 p. la celeridad durante 12 s al infligir daño con ataques a distancia.\n\n Si añades este dispositivo a un arma de ataque a distancia, el arma se ligará al alma. No se puede aplicar a objetos de nivel superior a 320.\nNecesitas ser de nivel 35"}
MultiLanguageSpellData['mx'][162203] = {name = "[q3]Filamento de megavatios", additional_info = "Hechizo de 2 seg\nHerramientas: Llave de tuerca arcoluz\nSin profesión:\nNecesita obras de ingeniería nivel 2\nComponentes:\nPiezas de resorte de engranaje (20)\nVendedor:\nNik Aroacero\nZona:\nLanza de Guerra\nCosto:\n1\n\n[q3]Filamento de megavatios\n[q2]Uso: Añade de forma permanente un dispositivo electrificado a un arma de ataque a distancia, lo que a veces aumenta 115 p. el golpe crítico durante 12 s cuando se inflige daño con ataques a distancia.\n\n Si añades este dispositivo a un arma de ataque a distancia, el arma se ligará al alma. No se puede aplicar a objetos superiores a nivel 320.\nNecesitas ser de nivel 35\n[q]\"Todo es mejor cuando está electrificado.\""}
MultiLanguageSpellData['mx'][162204] = {name = "Equipo de parapente goblin", additional_info = "Hechizo de 2 seg\nHerramientas: Llave de tuerca arcoluz\nComponentes:\nMena de hierro genuino (8), Piel suntuosa (5)\nVendedor:\nZaren Hoffle\nObjeto:\nIngeniería de Draenor\nCosto:\n100\nZona:\nCaída de la Luna\n\nVendedor:\nSean Atrapasta\nObjeto:\nIngeniería de Draenor\nCosto:\n100\nZona:\nAshran\n\n(5)\n[q2]Uso: Reduce tu velocidad de caída durante 2 min. (3 Min Reutilización)"}
MultiLanguageSpellData['mx'][162205] = {name = "[q3]Despojador a distancia de Findle", additional_info = "Hechizo de 2 seg\nHerramientas: Martillo de herrero\nSin profesión:\nNecesita obras de ingeniería nivel 2\nComponentes:\nPiezas de resorte de engranaje (50)\nVendedor:\nNik Aroacero\nZona:\nLanza de Guerra\nCosto:\n1\n\n[q3]Despojador a distancia de Findle\nSe liga al usarlo\nJuguete\n[q2]Uso: Obtiene el botín de un cadáver cercano. Solo puede usarse en Draenor. (3 Seg Reutilización)"}
MultiLanguageSpellData['mx'][162206] = {name = "[q3]Encogemundos", additional_info = "Hechizo de 2 seg\nHerramientas: Microajustador giromático\nComponentes:\nPiezas de resorte de engranaje (50)\nVendedor:\nNik Aroacero\nZona:\nLanza de Guerra\nCosto:\n1\n\n[q3]Encogemundos\nJuguete\n[q2]Uso: Encoge el mundo entero durante 5 min o hasta que ataques. (15 Min Reutilización)\nRequiereIngeniería de Draenor\n(1)\n[q]\"El uso excesivo puede provocar encogimiento permanente.\""}
MultiLanguageSpellData['mx'][162207] = {name = "Hombre sigiloso 54", additional_info = "Hechizo de 2 seg\nHerramientas: Microajustador giromático\nComponentes:\nMena de Roca Negra (2), Mena de hierro genuino (2), Florflechada de Nagrand (2)\nVendedor:\nZaren Hoffle\nObjeto:\nIngeniería de Draenor\nCosto:\n100\nZona:\nCaída de la Luna\n\nVendedor:\nSean Atrapasta\nObjeto:\nIngeniería de Draenor\nCosto:\n100\nZona:\nAshran\n\n(5)\n[q2]Uso: Oculta al usuario en un campo de sigilo siempre y cuando se quede quieto. No puede usarse en combate. El campo dura hasta 6 s después de moverse.\n\n El Hombre sigiloso comparte su tiempo de reutilización con las pociones que no sanan. No funciona en niveles superiores a 49. (5 Min Reutilización)\nNecesitas ser de nivel 35\n[q]\"¡La invisibilidad es para perdedores!\""}
MultiLanguageSpellData['mx'][162208] = {name = "[q2]Navaja gnómica suprema", additional_info = "Hechizo de 2 seg\nComponentes:\nPiezas de resorte de engranaje (5)\n[q2]Navaja gnómica suprema\n[q2]+10 p. de habilidad en minería de Draenor.\n +10 p. de habilidad en herboristería de Draenor.\n +10 p. de habilidad en desuello de Draenor.\n[q]\"Incluye todas las herramientas de las profesiones.\""}
MultiLanguageSpellData['mx'][162209] = {name = "[q3]Pico de hacha mecánico", additional_info = "Hechizo de 3.5 seg\nHerramientas: Llave de tuerca arcoluz\nSin profesión:\nNecesita obras de ingeniería nivel 3\nComponentes:\nPiezas de resorte de engranaje (50)\nVendedor:\nNik Aroacero\nZona:\nLanza de Guerra\nCosto:\n1\n\n[q3]Pico de hacha mecánico\n[q2]Uso: Te enseña a invocar este compañero.\n[q2]Invoca y retira a tu pico de hacha mecánico.\n1 - 80 ( 80)"}
MultiLanguageSpellData['mx'][162210] = {name = "[q3]Jabagélido mecánico casi vivo", additional_info = "Hechizo de 3.5 seg\nHerramientas: Microajustador giromático\nSin profesión:\nNecesita obras de ingeniería nivel 3\nComponentes:\nPiezas de resorte de engranaje (50), Piel suntuosa (40)\nVendedor:\nNik Aroacero\nZona:\nLanza de Guerra\nCosto:\n1\n\n[q3]Jabagélido mecánico casi vivo\n[q2]Uso: Te enseña a invocar este compañero.\n[q2]Haz clic con el botón derecho del ratón para invocar y retirar a tu jabalí mecánico casi vivo.\n1 - 80 ( 80)"}
MultiLanguageSpellData['mx'][162214] = {name = "[q3]Holograma personal", additional_info = "Hechizo de 2 seg\nHerramientas: Microajustador giromático\nSin profesión:\nNecesita obras de ingeniería nivel 3\nComponentes:\nPiezas de resorte de engranaje (50)\nVendedor:\nNik Aroacero\nZona:\nLanza de Guerra\nCosto:\n1\n\n[q3]Holograma personal\nSe liga al usarlo\nJuguete\n[q2]Uso: Crea un holograma temporario de ti mismo durante 1 min. (5 Min Reutilización)\n[q]\"La imagen puede reaccionar a algunas emociones.\""}
MultiLanguageSpellData['mx'][162216] = {name = "[q3]Centrifugador agujero de gusano", additional_info = "Hechizo de 2 seg\nHerramientas: Martillo de herrero , Llave de tuerca arcoluz\nComponentes:\nPiezas de resorte de engranaje (50)\nVendedor:\nNik Aroacero\nZona:\nLanza de Guerra\nCosto:\n1\n\n[q3]Centrifugador agujero de gusano\nSe liga al usarlo\nJuguete\n[q2]Uso: Crea un agujero de gusano giratorio que el ingeniero puede usar para viajar por Draenor. (4 H Reutilización)\nNecesitas ser de nivel 34\nRequiereIngeniería de Draenor\n(1)"}
MultiLanguageSpellData['mx'][162217] = {name = "[q3]Cañón de trueque", additional_info = "Hechizo de 2 seg\nHerramientas: Llave de tuerca arcoluz\nSin profesión:\nNecesita obras de ingeniería nivel 3\nComponentes:\nPiezas de resorte de engranaje (50), Cristal temporal\nVendedor:\nNik Aroacero\nZona:\nLanza de Guerra\nCosto:\n1\n\n[q3]Cañón de trueque\nSe liga al usarlo\n[q2]Uso: Cambia tu ubicación con otro miembro del grupo. No puede usarse en combate. (1 Min Reutilización)\n[q]\"Aviso: cambiar con alguien usando un silenciador neural es muy peligroso.\""}
